                        if (!value || depth > 5) return '';

                        if (typeof value === 'string' || typeof value === 'number') {
                            return contextual ? normalizeId(value) : '';
                        }

                        if (typeof value !== 'object') return '';
                        if (seen.has(value)) return '';
                        if (seen.size > 900) return '';

                        seen.add(value);

                        const exactKeys = [
                            'anilistId',
                            'anilistID',
                            'aniListId',
                            'anilist_id',
                            'ani_list_id',
                            'mediaId',
                            'media_id',
                            'animeId',
                            'anime_id'
                        ];

                        for (const key of exactKeys) {
                            if (!Object.prototype.hasOwnProperty.call(value, key)) continue;

                            const id = normalizeId(value[key]);
                            if (id) return id;
                        }

                        if (Object.prototype.hasOwnProperty.call(value, 'id') && (contextual || objectLooksLikeAniListMediaObject(value))) {
                            const id = normalizeId(value.id);
                            if (id) return id;
                        }

                        const keys = Object.keys(value);

                        for (const key of keys) {
                            const lowerKey = String(key).toLowerCase();
                            const nextContextual = contextual || /anilist|ani[_-]?list|anime|media|entry|card|details/.test(lowerKey);

                            if (!nextContextual && depth >= 3) continue;

                            const id = readAnilistIdFromObject(value[key], depth + 1, seen, nextContextual);
                            if (id) return id;
                        }

                        return '';
                    }

                    function getAnilistIdFromReactData(root) {
                        if (!root) return '';

                        const elements = [root];

                        if (root.querySelectorAll) {
                            root.querySelectorAll('a[href], [data-media-entry-card-body="true"], [data-media-entry-card-title-section-title="true"], [data-media-entry-card-body-image="true"]').forEach(el => elements.push(el));
                        }

                        for (const element of elements) {
                            const keys = Object.keys(element).filter(key => {
                                return key.indexOf('__reactProps$') === 0 ||
                                    key.indexOf('__reactFiber$') === 0 ||
                                    key.indexOf('__reactInternalInstance$') === 0;
                            });

                            for (const key of keys) {
                                const id = readAnilistIdFromObject(element[key], 0, new WeakSet(), false);
                                if (id) return id;
                            }
                        }

                        return '';
                    }

                    function getAnilistIdFromCard(card) {
                        if (!card) return '';

                        const directId = getStrictIdFromElement(card, true);
                        if (directId) return directId;

                        const childWithId = card.querySelector('[data-media-id], [data-anilist-id], [data-anilistid], [data-ani-list-id], [data-anilist-media-id], [data-media-anilist-id], [data-entry-anilist-id], [data-entry-media-id], [data-anime-id], [data-media-entry-id], [data-mediaentryid], [data-entry-id], [data-id]');
                        const childId = getStrictIdFromElement(childWithId, true);
                        if (childId) return childId;

                        const links = Array.from(card.querySelectorAll('a[href]'));
                        for (const link of links) {
                            const hrefId = getAnilistIdFromHref(link.getAttribute('href'));
                            if (hrefId) return hrefId;
                        }

                        const closestLink = card.closest ? card.closest('a[href]') : null;
                        const closestHrefId = closestLink ? getAnilistIdFromHref(closestLink.getAttribute('href')) : '';
                        if (closestHrefId) return closestHrefId;

                        const reactId = getAnilistIdFromReactData(card);
                        if (reactId) return reactId;

                        return '';
                    }

                    async function hasDubForAnimeCard(card) {
                        if (!card) return false;

                        const anilistId = getAnilistIdFromCard(card);
                        if (!anilistId) return false;

                        const ids = await loadDubIds();
                        if (!ids || ids.size === 0) return false;

                        card.dataset.amaDubAnilistId = anilistId;

                        return ids.has(anilistId);
                    }

                    window.__AMA_DUB_DEBUG__ = async function() {
                        const ids = await loadDubIds();
                        const cards = Array.from(document.querySelectorAll(mediaEntryCardQuery)).slice(0, 25).map(card => {
                            const anilistId = getAnilistIdFromCard(card);

                            return {
                                title: String(card.querySelector('[data-media-entry-card-title-section-title="true"]')?.textContent || '').trim(),
                                anilistId,
                                hasDub: ids ? ids.has(anilistId) : false,
                                href: card.querySelector('a[href]') ? card.querySelector('a[href]').getAttribute('href') : ''
                            };
                        });

                        return {
                            dubIdCount: ids ? ids.size : 0,
                            cards
                        };
                    };

                    function removeArrowArtifacts(root) {
                        if (!root || !isElement(root)) return;

                        if (root.matches('.ama-carousel-nav-btn')) {
                            root.remove();
                            return;
                        }

                        if (root.matches('.ama-manga-carousel-parent')) {
                            root.classList.remove('ama-manga-carousel-parent');
                        }

                        root.querySelectorAll('.ama-carousel-nav-btn').forEach(btn => btn.remove());

                        root.querySelectorAll('.ama-manga-carousel-parent').forEach(parent => {
                            parent.classList.remove('ama-manga-carousel-parent');
                        });
                    }

                    function cleanupCarousels(root) {
                        if (!root || !root.querySelectorAll) return;

                        if (root.matches && root.matches(targetGridsQuery)) {
                            root.classList.remove('ama-optimized-carousel');
                            root.dataset.amaCarouselEnhanced = "false";
                        }

                        root.querySelectorAll(targetGridsQuery).forEach(grid => {
                            grid.classList.remove('ama-optimized-carousel');
                            grid.dataset.amaCarouselEnhanced = "false";
                        });
                    }

                    function isRandomSearchSvg(svg) {
                        if (!svg || svg.tagName.toLowerCase() !== 'svg') return false;

                        const path = svg.querySelector('path');
                        if (!path) return false;

                        return path.getAttribute('d') === randomSearchIconPath;
                    }

                    function shouldRemoveRandomSearchSvg(svg) {
                        if (!svg || svg.classList.contains('ama-search-icon')) return false;
                        if (svg.closest('.ama-search-wrapper')) return false;
                        if (svg.closest('button, a, [role="button"], [role="tab"], [role="menuitem"]')) return false;

                        const parent = svg.parentElement;
                        if (!parent) return false;

                        const parentRect = parent.getBoundingClientRect();
                        const svgRect = svg.getBoundingClientRect();

                        if (!parentRect || !svgRect || parentRect.width < 240) return false;

                        const svgCenterX = svgRect.left + (svgRect.width / 2) - parentRect.left;
                        const isCentered = svgCenterX > parentRect.width * 0.35 && svgCenterX < parentRect.width * 0.65;

                        return isCentered;
                    }

                    function removeRandomSearchIcons(root) {
                        if (!featureSettings.betterMarketplace) return;
                        if (!root) return;

                        const svgs = [];

                        if (root.matches && root.matches('svg')) {
                            svgs.push(root);
                        }

                        if (root.querySelectorAll) {
                            root.querySelectorAll('svg').forEach(svg => svgs.push(svg));
                        }

                        svgs.forEach(svg => {
                            if (!isRandomSearchSvg(svg)) return;
                            if (!shouldRemoveRandomSearchSvg(svg)) return;

                            svg.setAttribute('data-ama-random-search-icon', 'true');
                            svg.remove();
                        });
                    }

                    function optimizeImages(root) {
                        if (!root || !root.querySelectorAll) return;

                        root.querySelectorAll('img:not([data-ama-image-optimized="true"])').forEach(img => {
                            img.dataset.amaImageOptimized = "true";
                            img.loading = 'lazy';
                            img.decoding = 'async';

                            try {
                                img.fetchPriority = 'low';
                            } catch (_) {}
                        });
                    }

                    function enhanceCarouselGrid(grid) {
                        if (!featureSettings.carousels) return;
                        if (!grid || grid.dataset.amaCarouselEnhanced === "true") return;

                        grid.dataset.amaCarouselEnhanced = "true";
                        grid.classList.add('ama-optimized-carousel');

                        optimizeImages(grid);
                    }

                    const dubObserver = new IntersectionObserver(entries => {
                        entries.forEach(entry => {
                            if (!entry.isIntersecting) return;

                            const card = entry.target;
                            dubObserver.unobserve(card);

                            if (!featureSettings.subDubIcons) return;

                            const badge = card.querySelector('.ama-media-badge.dub');
                            if (!badge) return;

                            badge.hidden = true;
                            badge.setAttribute('aria-hidden', 'true');

                            hasDubForAnimeCard(card).then(hasDub => {
                                if (!badge.isConnected) return;
                                if (!featureSettings.subDubIcons) return;

                                if (hasDub) {
                                    badge.hidden = false;
                                    badge.setAttribute('aria-hidden', 'false');
                                } else {
                                    badge.hidden = true;
                                    badge.setAttribute('aria-hidden', 'true');
                                }
                            });
                        });
                    }, {
                        root: null,
                        rootMargin: '500px 900px',
                        threshold: 0.01
                    });

                    function isAnimeCard(card) {
                        if (!card) return false;

                        const explicitType = String(
                            card.getAttribute('data-media-type') ||
                            card.getAttribute('data-entry-type') ||
                            card.getAttribute('data-media-kind') ||
                            ''
                        ).toLowerCase();

                        if (explicitType.includes('manga') || explicitType.includes('novel') || explicitType.includes('book')) {
                            return false;
                        }

                        if (explicitType.includes('anime')) {
                            return true;
                        }

                        if (card.closest('[data-manga-page-container="true"], [data-manga-entry-screen="true"], [data-manga-entry-page="true"]')) {
                            return false;
                        }

                        const lowerPath = String(window.location.pathname || '').toLowerCase();

                        if (lowerPath.includes('manga') || lowerPath.includes('novel') || lowerPath.includes('book')) {
                            return false;
                        }

                        const link = card.querySelector('a[href]');
                        const href = link ? String(link.getAttribute('href') || '').toLowerCase() : '';

                        if (href.includes('manga') || href.includes('novel') || href.includes('book')) {
                            return false;
                        }

                        return true;
                    }

                    function removeMediaBadges(card) {
                        if (!card) return;

                        const yearEl = card.querySelector('[data-media-entry-card-title-section-year-season="true"]');
                        const row = yearEl ? yearEl.parentElement : null;

                        if (row) {
                            row.classList.remove('ama-media-meta-row');
                            row.querySelectorAll('.ama-media-badges').forEach(el => el.remove());
                        }

                        card.dataset.amaMediaBadgeEnhanced = "false";
                    }

                    function cleanupAllMediaBadges(root) {
                        if (!root) return;

                        if (root.matches && root.matches(mediaEntryCardQuery)) {
                            removeMediaBadges(root);
                        }

                        if (root.querySelectorAll) {
                            root.querySelectorAll(mediaEntryCardQuery).forEach(removeMediaBadges);
                        }
                    }

                    function enhanceMediaEntryCard(card) {
                        if (!featureSettings.subDubIcons) {
                            removeMediaBadges(card);
                            return;
                        }

                        if (!card) return;

                        if (!isAnimeCard(card)) {
                            removeMediaBadges(card);
                            return;
                        }

                        if (card.dataset.amaMediaBadgeEnhanced === "true" && card.querySelector('.ama-media-badges')) {
                            const existingDubBadge = card.querySelector('.ama-media-badge.dub');

                            if (existingDubBadge) {
                                existingDubBadge.hidden = true;
                                existingDubBadge.setAttribute('aria-hidden', 'true');
                                dubObserver.observe(card);
                            }

                            return;
                        }

                        const yearEl = card.querySelector('[data-media-entry-card-title-section-year-season="true"]');
                        const titleEl = card.querySelector('[data-media-entry-card-title-section-title="true"]');

                        if (!yearEl || !titleEl) return;

                        const row = yearEl.parentElement;
                        if (!row) return;

                        card.dataset.amaMediaBadgeEnhanced = "true";

                        row.classList.add('ama-media-meta-row');

                        row.querySelectorAll('.ama-media-badges').forEach(el => el.remove());

                        const badges = document.createElement('span');
                        badges.className = 'ama-media-badges';

                        const dubBadge = document.createElement('span');
                        dubBadge.className = 'ama-media-badge dub';
                        dubBadge.title = 'Dub available';
                        dubBadge.setAttribute('aria-label', 'Dub available');
                        dubBadge.setAttribute('aria-hidden', 'true');
                        dubBadge.hidden = true;
                        dubBadge.innerHTML = MIC_ICON;

                        const ccBadge = document.createElement('span');
                        ccBadge.className = 'ama-media-badge cc';
                        ccBadge.title = 'Captions';
                        ccBadge.setAttribute('aria-label', 'Captions');
                        ccBadge.innerHTML = CC_ICON;

                        badges.appendChild(dubBadge);
                        badges.appendChild(ccBadge);

                        row.appendChild(badges);

                        card.dataset.amaDubTitle = titleEl.textContent.trim();
                        card.dataset.amaDubMalId = card.getAttribute('data-media-mal-id') || '';
                        card.dataset.amaDubAnilistId = getAnilistIdFromCard(card) || card.getAttribute('data-media-id') || '';

                        dubObserver.observe(card);
                    }


                    function getTrimmedText(element) {
                        if (!element) return '';

                        return String(element.textContent || '').replace(/\s+/g, ' ').trim();
                    }

                    function getEpisodeCardData(card) {
                        const heading = getTrimmedText(card.querySelector('[data-episode-grid-item-title="true"]'));
                        const episodeTitle = String(
                            card.getAttribute('data-episode-title') ||
                            getTrimmedText(card.querySelector('[data-episode-grid-item-episode-title="true"]')) ||
                            card.getAttribute('data-title') ||
                            heading ||
                            'Episode'
                        ).trim();

                        const description = String(
                            card.getAttribute('data-description') ||
                            getTrimmedText(card.querySelector('[data-episode-grid-item-episode-description="true"]')) ||
                            'No episode description available.'
                        ).trim();

                        const fileName = String(
                            card.getAttribute('data-file-name') ||
                            card.getAttribute('data-filename') ||
                            getTrimmedText(card.querySelector('[data-episode-grid-item-filename="true"]')) ||
                            ''
                        ).trim();

                        const episodeNumber = String(
                            card.getAttribute('data-episode-number') ||
                            card.getAttribute('data-progress-number') ||
                            ''
                        ).trim();

                        const progressNumber = String(card.getAttribute('data-progress-number') || '').trim();
                        const title = String(card.getAttribute('data-title') || heading || (episodeNumber ? 'Episode ' + episodeNumber : 'Episode')).trim();
                        const durationText = (() => {
                            const titleEl = card.querySelector('[data-episode-grid-item-title="true"]');
                            if (!titleEl) return '';

                            const spans = Array.from(titleEl.querySelectorAll('span')).map(getTrimmedText).filter(Boolean);
                            if (spans.length >= 2) return spans.slice(1).join(' ');
                            return '';
                        })();

                        const imageEl = card.querySelector('[data-episode-grid-item-image="true"]');
                        const imageSrc = imageEl ? String(
                            imageEl.getAttribute('src') ||
                            imageEl.getAttribute('data-src') ||
                            imageEl.getAttribute('data-lazy-src') ||
                            ''
                        ).trim() : '';

                        const watchedValue = String(card.getAttribute('data-is-watched') || '').toLowerCase();
                        const watched = watchedValue === 'true';
                        const invalid = String(card.getAttribute('data-is-invalid') || '').toLowerCase() === 'true';
                        const mediaId = String(card.getAttribute('data-media-id') || '').trim();

                        return {
                            title,
                            episodeTitle,
                            description,
                            fileName,
                            episodeNumber,
                            progressNumber,
                            durationText,
                            imageSrc,
                            watched,
                            invalid,
                            mediaId,
                            key: [
                                title,
                                episodeTitle,
                                description,
                                fileName,
                                episodeNumber,
                                progressNumber,
                                durationText,
                                imageSrc,
                                watchedValue,
                                invalid,
                                mediaId
                            ].join('|')
                        };
                    }

                    function createPill(text, className) {
                        const pill = document.createElement('span');
                        pill.className = 'ama-episode-hover-card__pill' + (className ? ' ' + className : '');
                        pill.textContent = text;
                        return pill;
                    }

                    function createEpisodeHoverCard(data) {
                        const overlay = document.createElement('div');
                        overlay.className = 'ama-episode-hover-card';
                        overlay.setAttribute('aria-hidden', 'true');

                        const imageWrap = document.createElement('div');
                        imageWrap.className = 'ama-episode-hover-card__image-wrap';

                        if (data.imageSrc) {
                            const image = document.createElement('img');
                            image.className = 'ama-episode-hover-card__image';
                            image.alt = '';
                            image.loading = 'lazy';
                            image.decoding = 'async';
                            image.src = data.imageSrc;
                            imageWrap.appendChild(image);
                        } else {
                            const imagePlaceholder = document.createElement('div');
                            imagePlaceholder.className = 'ama-episode-hover-card__image-placeholder';
                            imageWrap.appendChild(imagePlaceholder);
                        }

                        const content = document.createElement('div');
                        content.className = 'ama-episode-hover-card__content';

                        const top = document.createElement('div');
                        top.className = 'ama-episode-hover-card__top';

                        top.appendChild(createPill(data.title || 'Episode', ''));

                        if (data.durationText) {
                            top.appendChild(createPill(data.durationText, ''));
                        }

                        top.appendChild(createPill(data.watched ? 'Watched' : 'Unwatched', data.watched ? 'is-watched' : 'is-unwatched'));

                        if (data.invalid) {
                            top.appendChild(createPill('Invalid file', ''));
                        }

                        const title = document.createElement('h4');
                        title.className = 'ama-episode-hover-card__title';
                        title.textContent = data.episodeTitle || data.title || 'Episode';

                        const description = document.createElement('p');
                        description.className = 'ama-episode-hover-card__description';
                        description.textContent = data.description || 'No episode description available.';

                        content.appendChild(top);
                        content.appendChild(title);
                        content.appendChild(description);

                        const metaParts = [];

                        if (data.episodeNumber) {
                            metaParts.push('Episode: ' + data.episodeNumber);
                        }

                        if (data.progressNumber && data.progressNumber !== data.episodeNumber) {
                            metaParts.push('Progress: ' + data.progressNumber);
                        }

                        if (data.mediaId) {
                            metaParts.push('Media ID: ' + data.mediaId);
                        }

                        if (metaParts.length) {
                            const meta = document.createElement('div');
                            meta.className = 'ama-episode-hover-card__meta';
                            meta.textContent = metaParts.join(' | ');
                            content.appendChild(meta);
                        }

                        if (data.fileName) {
                            const file = document.createElement('div');
                            file.className = 'ama-episode-hover-card__file';
                            file.textContent = data.fileName;
                            content.appendChild(file);
                        }

                        overlay.appendChild(imageWrap);
                        overlay.appendChild(content);

                        return overlay;
                    }

                    function isEpisodeInfoButton(button) {
                        if (!button || !button.matches || !button.matches('button')) return false;
                        if (!button.closest(episodeGridItemQuery)) return false;
                        if (String(button.getAttribute('aria-haspopup') || '').toLowerCase() !== 'dialog') return false;

                        const infoPath = button.querySelector('svg path[d^="M12 2C6.48"]');

                        return !!infoPath;
                    }

                    function removeEpisodeInfoButtons(root) {
                        if (!featureSettings.betterEpisodeCards) return;
                        if (!root) return;

                        const buttons = [];

                        if (root.matches && root.matches('button')) {
                            buttons.push(root);
                        }

                        if (root.querySelectorAll) {
                            root.querySelectorAll('button[aria-haspopup="dialog"]').forEach(button => buttons.push(button));
                        }

                        buttons.forEach(button => {
                            if (!isEpisodeInfoButton(button)) return;

                            button.setAttribute('data-ama-episode-info-button', 'true');
                            button.remove();
                        });
                    }

                    function cleanupEpisodeCard(card) {
                        if (!card) return;

                        card.querySelectorAll('.ama-episode-hover-card').forEach(el => el.remove());
                        card.dataset.amaBetterEpisodeCardsEnhanced = "false";
                        delete card.dataset.amaBetterEpisodeCardsKey;
                    }

                    function cleanupAllEpisodeCards(root) {
                        if (!root) return;

                        if (root.matches && root.matches(episodeGridItemQuery)) {
                            cleanupEpisodeCard(root);
                        }

                        if (root.querySelectorAll) {
                            root.querySelectorAll(episodeGridItemQuery).forEach(cleanupEpisodeCard);
                        }
                    }

                    function enhanceEpisodeCard(card) {
                        if (!card) return;

                        if (!featureSettings.betterEpisodeCards) {
                            cleanupEpisodeCard(card);
                            return;
                        }

                        removeEpisodeInfoButtons(card);

                        const data = getEpisodeCardData(card);

                        if (card.dataset.amaBetterEpisodeCardsEnhanced === "true" && card.dataset.amaBetterEpisodeCardsKey === data.key) {
                            return;
                        }

                        card.querySelectorAll('.ama-episode-hover-card').forEach(el => el.remove());

                        const overlay = createEpisodeHoverCard(data);
                        card.appendChild(overlay);

                        card.dataset.amaBetterEpisodeCardsEnhanced = "true";
                        card.dataset.amaBetterEpisodeCardsKey = data.key;
                    }

                    function filterCards(container, term) {
                        const normalized = String(term || '').toLowerCase();

                        container.querySelectorAll('.group\\\\/extension-card').forEach(card => {
                            card.style.display = card.innerText.toLowerCase().includes(normalized) ? 'flex' : 'none';
                        });
                    }

                    function cleanupBetterMarketplace(root) {
                        if (!root) return;

                        const cards = [];

                        if (root.matches && root.matches(cardQuery)) {
                            cards.push(root);
                        }

                        if (root.querySelectorAll) {
                            root.querySelectorAll(cardQuery).forEach(card => cards.push(card));
                        }

                        cards.forEach(card => {
                            const header = card.querySelector(':scope > .ama-header-container');

                            if (header) {
                                const title = header.querySelector('h3');

                                if (title) {
                                    card.insertBefore(title, header);
                                }

                                header.remove();
                            }

                            card.dataset.amaEnhanced = "false";
                        });

                        if (root.querySelectorAll) {
                            root.querySelectorAll('.ama-modal').forEach(modal => modal.remove());
                        }
                    }

                    function enhanceExtensionCard(card) {
                        if (!featureSettings.betterMarketplace) return;
                        if (!card || card.dataset.amaEnhanced === "true") return;

                        const titleEl = card.querySelector('h3');
                        const grid = card.querySelector('.grid');

                        if (!titleEl || !grid) return;

                        card.dataset.amaEnhanced = "true";

                        const header = document.createElement('div');
                        header.className = 'ama-header-container';

                        const left = document.createElement('div');
                        left.className = 'ama-header-left';
                        left.appendChild(titleEl);

                        const viewBtn = document.createElement('button');
                        viewBtn.type = 'button';
                        viewBtn.className = 'ama-view-btn';
                        viewBtn.innerText = 'View All';
                        left.appendChild(viewBtn);

                        const right = document.createElement('div');
                        right.className = 'ama-header-right';

                        const searchWrapper = document.createElement('div');
                        searchWrapper.className = 'ama-search-wrapper';

                        const searchIcon = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
                        searchIcon.setAttribute('class', 'ama-search-icon');
                        searchIcon.setAttribute('viewBox', '0 0 24 24');
                        searchIcon.setAttribute('fill', 'none');
                        searchIcon.setAttribute('stroke', 'white');
                        searchIcon.setAttribute('stroke-width', '2');
                        searchIcon.setAttribute('stroke-linecap', 'round');
                        searchIcon.setAttribute('stroke-linejoin', 'round');
                        searchIcon.innerHTML = '<circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/>';

                        const search = document.createElement('input');
                        search.className = 'ama-search-input';
                        search.placeholder = 'Search...';

                        searchWrapper.appendChild(searchIcon);
                        searchWrapper.appendChild(search);
                        right.appendChild(searchWrapper);

                        header.appendChild(left);
                        header.appendChild(right);
                        card.prepend(header);

                        let searchTimer = null;

                        search.oninput = (e) => {
                            clearTimeout(searchTimer);
                            searchTimer = setTimeout(() => {
                                filterCards(grid, e.target.value);
                            }, 140);
                        };

                        viewBtn.onclick = () => {
                            const modal = document.createElement('div');
                            modal.className = 'ama-modal';

                            modal.innerHTML =
                                '<button type="button" class="ama-modal-close">Close</button>' +
                                '<h2 style="margin-top:0; margin-bottom:16px; font-size:32px;">Full Catalog</h2>' +
                                '<div class="ama-search-wrapper" style="margin-bottom:24px;">' +
                                    '<svg class="ama-search-icon" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' +
                                        '<circle cx="11" cy="11" r="8"/>' +
                                        '<line x1="21" y1="21" x2="16.65" y2="16.65"/>' +
                                    '</svg>' +
                                    '<input id="ama-modal-search" class="ama-search-input" placeholder="Search..." style="width:300px;"/>' +
                                '</div>' +
                                '<div id="ama-modal-content"></div>';

                            const items = Array.from(grid.querySelectorAll('.group\\\\/extension-card'));
                            const grouped = items.reduce((acc, item) => {
                                const badges = item.querySelectorAll('.UI-Badge__root');
                                const author = badges[1]?.innerText?.trim() || 'Unknown';

                                if (!acc[author]) acc[author] = [];
                                acc[author].push(item);

                                return acc;
                            }, {});

                            const content = modal.querySelector('#ama-modal-content');
                            const fragment = document.createDocumentFragment();

                            Object.keys(grouped).sort().forEach(author => {
                                const row = document.createElement('div');
                                row.className = 'modal-row';

                                const title = document.createElement('div');
                                title.className = 'modal-row-title';
                                title.textContent = author;

                                const rowGrid = document.createElement('div');
                                rowGrid.className = 'ama-carousel-row';

                                grouped[author].forEach(item => {
                                    const clone = item.cloneNode(true);
                                    clone.querySelectorAll('button').forEach(button => button.remove());
                                    optimizeImages(clone);
                                    rowGrid.appendChild(clone);
                                });

                                row.appendChild(title);
                                row.appendChild(rowGrid);
                                fragment.appendChild(row);
                            });

                            content.appendChild(fragment);

                            const modalSearch = modal.querySelector('#ama-modal-search');
                            let modalSearchTimer = null;

                            modalSearch.oninput = (e) => {
                                clearTimeout(modalSearchTimer);

                                modalSearchTimer = setTimeout(() => {
                                    filterCards(modal, e.target.value);

                                    modal.querySelectorAll('.modal-row').forEach(row => {
                                        const visible = Array.from(row.querySelectorAll('.group\\\\/extension-card')).some(card => card.style.display !== 'none');
                                        row.style.display = visible ? '' : 'none';
                                    });
                                }, 140);
                            };

                            modal.querySelector('.ama-modal-close').onclick = () => modal.remove();

                            modal.onclick = (e) => {
                                if (e.target === modal) modal.remove();
                            };

                            document.body.appendChild(modal);
                        };
                    }

                    function processRoot(root) {
                        if (!root) return;

                        if (!featureSettings.betterMarketplace) {
                            cleanupBetterMarketplace(root);
                        }

                        if (!featureSettings.carousels) {
                            cleanupCarousels(root);
                        }

                        if (!featureSettings.subDubIcons) {
                            cleanupAllMediaBadges(root);
                        }

                        if (!featureSettings.betterEpisodeCards) {
                            cleanupAllEpisodeCards(root);
                        }

                        if (root === document) {
                            document.querySelectorAll('.ama-carousel-nav-btn').forEach(btn => btn.remove());

                            document.querySelectorAll('.ama-manga-carousel-parent').forEach(parent => {
                                parent.classList.remove('ama-manga-carousel-parent');
                            });

                            if (featureSettings.carousels) {
                                document.querySelectorAll(targetGridsQuery).forEach(grid => {
                                    enhanceCarouselGrid(grid);
                                });
                            }

                            if (featureSettings.subDubIcons) {
                                document.querySelectorAll(mediaEntryCardQuery).forEach(card => {
                                    enhanceMediaEntryCard(card);
                                });
                            }

                            if (featureSettings.betterMarketplace) {
                                document.querySelectorAll(cardQuery).forEach(card => {
                                    enhanceExtensionCard(card);
                                });
                            }

                            if (featureSettings.betterEpisodeCards) {
                                document.querySelectorAll(episodeGridItemQuery).forEach(card => {
                                    enhanceEpisodeCard(card);
                                });

                                removeEpisodeInfoButtons(document);
                            }

                            optimizeImages(document);
                            removeRandomSearchIcons(document);
                            return;
                        }

                        removeArrowArtifacts(root);
                        removeRandomSearchIcons(root);

                        if (root.matches && root.matches(targetGridsQuery)) {
                            enhanceCarouselGrid(root);
                            return;
                        }

                        if (root.matches && root.matches(mediaEntryCardQuery)) {
                            enhanceMediaEntryCard(root);
                            return;
                        }

                        if (root.matches && root.matches(episodeGridItemQuery)) {
                            enhanceEpisodeCard(root);
                            return;
                        }

                        if (root.matches && root.matches(cardQuery)) {
                            enhanceExtensionCard(root);
                            return;
                        }

                        if (root.querySelectorAll) {
                            if (featureSettings.carousels) {
                                root.querySelectorAll(targetGridsQuery).forEach(grid => {
                                    enhanceCarouselGrid(grid);
                                });
                            }

                            if (featureSettings.subDubIcons) {
                                root.querySelectorAll(mediaEntryCardQuery).forEach(card => {
                                    enhanceMediaEntryCard(card);
                                });
                            }

                            if (featureSettings.betterMarketplace) {
                                root.querySelectorAll(cardQuery).forEach(card => {
                                    enhanceExtensionCard(card);
                                });
                            }

                            if (featureSettings.betterEpisodeCards) {
                                root.querySelectorAll(episodeGridItemQuery).forEach(card => {
                                    enhanceEpisodeCard(card);
                                });

                                removeEpisodeInfoButtons(root);
                            }

                            optimizeImages(root);
                        }
                    }

                    const queuedRoots = new Set();
                    let scheduled = false;

                    function flushQueue() {
                        scheduled = false;

                        const roots = Array.from(queuedRoots);
                        queuedRoots.clear();

                        for (const root of roots) {
                            processRoot(root);
                        }
                    }

                    function scheduleRoot(root) {
                        if (!root || !isElement(root)) return;

                        queuedRoots.add(root);

                        if (scheduled) return;
                        scheduled = true;

                        if ('requestIdleCallback' in window) {
                            window.requestIdleCallback(flushQueue, { timeout: 700 });
                        } else {
                            setTimeout(flushQueue, 220);
                        }
                    }

                    window.__AMA_SAVE_SETTINGS__ = function(nextSettings) {
                        featureSettings = Object.assign({}, defaultSettings, nextSettings || {});
                        writeBrowserSettings(featureSettings);

                        setBodyFlags();

                        if (!featureSettings.betterMarketplace) {
                            cleanupBetterMarketplace(document);
                        }

                        if (!featureSettings.carousels) {
                            cleanupCarousels(document);
                        }

                        if (!featureSettings.subDubIcons) {
                            cleanupAllMediaBadges(document);
                        }

                        if (!featureSettings.betterEpisodeCards) {
                            cleanupAllEpisodeCards(document);
                        }

                        scheduleRoot(document.body || document.documentElement);
                    };

                    window.__AMA_APPLY_SETTINGS__ = window.__AMA_SAVE_SETTINGS__;

                    setBodyFlags();
                    writeBrowserSettings(featureSettings);
                    processRoot(document);

                    const observer = new MutationObserver((mutations) => {
                        for (const mutation of mutations) {
                            for (const node of mutation.addedNodes) {
                                if (!isElement(node)) continue;

                                if (
                                    node.matches('.ama-carousel-nav-btn') ||
                                    node.matches('.ama-manga-carousel-parent') ||
                                    node.matches(targetGridsQuery) ||
                                    node.matches(mediaEntryCardQuery) ||
                                    node.matches(episodeGridItemQuery) ||
                                    node.matches(cardQuery) ||
                                    node.matches('button[aria-haspopup="dialog"]') ||
                                    node.matches('svg')
                                ) {
                                    scheduleRoot(node);
                                    continue;
                                }

                                if (
                                    node.querySelector &&
                                    node.querySelector(arrowQuery + ', ' + targetGridsQuery + ', ' + mediaEntryCardQuery + ', ' + episodeGridItemQuery + ', ' + cardQuery + ', button[aria-haspopup="dialog"], svg')
                                ) {
                                    scheduleRoot(node);
                                }
                            }
                        }
                    });

                    observer.observe(document.body, {
                        childList: true,
                        subtree: true
                    });
                })();
            `);

            body.append(script);
        });
    });
}
